void timeout_f_update (Timeout timeout, Exec_Func new_func)
{
	CRITICAL ;

	#define TIMEOUT_F	((Timeout_F *)timeout)

  	C_ENTER ;	
    {
		TIMEOUT_F->exec_func = new_func ;
    }
  	C_LEAVE ;

	#undef TIMEOUT_F
}

